package com.example.smartpantry.ui;

import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;

public class SettingsActivity extends Activity { public void onCreate(Bundle b){super.onCreate(b);android.content.SharedPreferences prefs=getSharedPreferences("settings",0);LinearLayout p=Ui.page(this);p.addView(Ui.title(this,"Settings"));p.addView(Ui.label(this,"Personalise your pantry experience."));Switch alerts=new Switch(this);alerts.setText("Show expiring-soon alerts");alerts.setTextSize(16);alerts.setTextColor(Ui.text);alerts.setPadding(24,20,24,20);alerts.setChecked(prefs.getBoolean("alerts",true));alerts.setOnCheckedChangeListener((v,checked)->prefs.edit().putBoolean("alerts",checked).apply());p.addView(alerts);TextView about=Ui.label(this,"Smart Pantry Manager\n\nStrict matching means a recipe is suggested only when every required ingredient is present in sufficient quantity. No shopping trips required.");about.setTextSize(16);about.setPadding(24,32,24,32);p.addView(about);Button back=Ui.button(this,"Back to pantry");LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,58);lp.setMargins(24,16,24,16);p.addView(back,lp);back.setOnClickListener(v->finish());p.addView(Ui.nav(this,v->startActivity(new Intent(this,MainActivity.class)),v->startActivity(new Intent(this,SuggestedRecipesActivity.class)),v->{}));setContentView(p);}}
